const body = $input.first().json.body || $input.first().json || {};
const messageText = (body.messageText || body.message || '').trim();
const senderPhone = body.senderPhone || body.phone || 'Unknown';
const senderName = body.senderName || body.name || 'Valued Patient';
const eventType = body.event || 'whatsapp_message';
const session = body.session || {};

const lower = messageText.toLowerCase();

// 1. Patient Name Extraction
let patientName = session.patientName || senderName;
const nameMatch = messageText.match(/(?:my name is|i am|this is|call me)\s+([a-zA-Z\s]{2,25})/i);
if (nameMatch && nameMatch[1]) {
  patientName = nameMatch[1].trim();
}

// 2. Emergency & Acute Pain Detection
const isEmergency = /pain|emergency|bleeding|swelling|broken|ache|severe|trauma|urgent|infection|fell|cracked/i.test(lower);

// 3. Service Detection
let currentService = session.service || 'General Dental Consultation & Checkup';
if (isEmergency) {
  currentService = 'Emergency Toothache / Acute Dental Care';
} else if (/clean|hygiene|scale/i.test(lower)) {
  currentService = 'Routine Cleaning & Hygiene Care';
} else if (/whiten/i.test(lower)) {
  currentService = 'Professional Teeth Whitening';
} else if (/filling|cavity|crown|implant/i.test(lower)) {
  currentService = 'Restorative Dentistry / Filling & Crown';
} else if (/brace|aligner|invisalign/i.test(lower)) {
  currentService = 'Orthodontics & Teeth Alignment';
}

let currentTime = session.preferredTime || '';
let stage = session.stage || 'INIT';
let isBooked = false;
let reply = '';

// Check if user just sent a basic greeting
const isGreetingOnly = /^(hi|hello|hey|salam|assalam|aoa|good morning|good afternoon|good evening)[\s!.]*$/i.test(lower);

if (isEmergency) {
  isBooked = true;
  stage = 'EMERGENCY_CONFIRMED';
  currentTime = 'Today (Immediate Walk-In / Triage)';
  reply = `🚨 Urgent Care Notice: Hi ${patientName}! Our clinical triage has flagged your case as HIGH PRIORITY / EMERGENCY.\n\nPlease walk directly into our emergency clinic at 123 Healthcare Blvd. Our on-duty dentist is being alerted right now. We are ready for you!`;

} else if (/fee|cost|price|charge|rate|how much/i.test(lower)) {
  // --- INQUIRY: FEES ---
  isBooked = false;
  reply = `Our standard dental consultation and comprehensive digital exam is $50 / Rs. 1,500. Routine teeth cleanings are $80 / Rs. 2,500.`;
  if (currentTime) {
    reply += ` Your appointment is currently reserved for ${currentTime}!`;
  } else {
    reply += ` Would you like to schedule an appointment for tomorrow morning or afternoon?`;
  }

} else if (/where|location|address|map|place/i.test(lower)) {
  // --- INQUIRY: LOCATION ---
  isBooked = false;
  reply = `Apex Dental Clinic is located at 123 Healthcare Blvd, Medical District. Free parking is available for all patients!`;
  if (currentTime) {
    reply += ` We look forward to seeing you at ${currentTime}!`;
  } else {
    reply += ` Would you like to book a morning or afternoon slot?`;
  }

} else {
  // --- TIME PARSING & OPERATING HOURS VALIDATION ---
  let parsedHour = null;
  let isAm = false;
  let isPm = false;

  // Match expressions like "4 00 AM", "4:00 am", "4 am", "4 00 PM", "4:00 pm", "4 pm", "4:00", etc.
  const timeMatch = lower.match(/(?:at|on|with|time)?\s*(\d{1,2})(?::|\s+)?(\d{2})?\s*(am|pm)?/i);
  if (timeMatch && !/^\d{7,}$/.test(messageText.replace(/\D/g, ''))) {
    const rawH = parseInt(timeMatch[1], 10);
    const ampm = timeMatch[3] ? timeMatch[3].toLowerCase() : '';
    if (rawH >= 1 && rawH <= 12) {
      parsedHour = rawH;
      if (ampm === 'am') isAm = true;
      if (ampm === 'pm') isPm = true;
      if (!ampm) {
        if (rawH >= 8 && rawH <= 11) isAm = true;
        else if (rawH >= 1 && rawH <= 7) isPm = true;
      }
    }
  }

  // Check impossible / closed hours (9 AM to 6 PM Monday to Saturday)
  const isNightOrEarly = isAm && (parsedHour === 12 || (parsedHour >= 1 && parsedHour <= 7));
  const isLateNight = isPm && (parsedHour >= 8 && parsedHour <= 11);

  if (isNightOrEarly || isLateNight || /night|midnight/i.test(lower)) {
    // Patient asked for 4:00 AM or night time
    isBooked = false;
    const requestedStr = parsedHour ? `${parsedHour}:00 AM` : 'that hour';
    const recommendedPm = (parsedHour && parsedHour >= 1 && parsedHour <= 6) ? `${parsedHour}:00 PM` : '4:00 PM';
    reply = `Our clinic is open Monday through Saturday from 9:00 AM to 6:00 PM. We are closed at ${requestedStr}, but we can schedule your appointment for Tomorrow Afternoon at ${recommendedPm} or Tomorrow Morning at 10:00 AM! Would ${recommendedPm} work for you?`;
    currentTime = `Pending (Recommended ${recommendedPm})`;
    stage = 'AWAITING_TIME';

  } else if (/change.*(?:morning\s+to\s+afternoon|to\s+afternoon)|switch.*afternoon/i.test(lower) || (lower.includes('afternoon') && lower.includes('change'))) {
    // Patient asks to switch to afternoon
    isBooked = false;
    currentTime = 'Tomorrow Afternoon';
    stage = 'AWAITING_TIME';
    reply = `Sure! We can switch your appointment to tomorrow afternoon. We have open slots at 2:00 PM, 3:30 PM, 4:00 PM, and 5:00 PM. Which time suits you best?`;

  } else if (parsedHour) {
    // Patient confirms specific valid time like "4 00 PM" or "10:00 AM"
    isBooked = true;
    const period = isPm ? 'PM' : 'AM';
    currentTime = `Tomorrow at ${parsedHour}:00 ${period}`;
    stage = 'BOOKED';
    reply = `🎉 Perfect, ${patientName}! Your appointment with Dr. Sarah at Apex Dental Clinic is officially confirmed for ${currentTime} for ${currentService}.\n\n📍 Location: 123 Healthcare Blvd\nWe have updated your slot on our calendar. See you then!`;

  } else if (lower.includes('afternoon')) {
    isBooked = true;
    currentTime = 'Tomorrow Afternoon (2:30 PM)';
    stage = 'BOOKED';
    reply = `🎉 Perfect, ${patientName}! Your appointment with Dr. Sarah at Apex Dental Clinic is officially confirmed for ${currentTime} for ${currentService}.\n\n📍 Location: 123 Healthcare Blvd\nWe have reserved your slot. See you then!`;

  } else if (lower.includes('morning')) {
    isBooked = true;
    currentTime = 'Tomorrow Morning (10:00 AM)';
    stage = 'BOOKED';
    reply = `🎉 Perfect, ${patientName}! Your appointment with Dr. Sarah at Apex Dental Clinic is officially confirmed for ${currentTime} for ${currentService}.\n\n📍 Location: 123 Healthcare Blvd\nWe have reserved your slot. See you then!`;

  } else if (isGreetingOnly || stage === 'INIT' || eventType === 'whatsapp_missed_call') {
    isBooked = false;
    stage = 'AWAITING_TIME';
    reply = `Hi ${patientName}! This is Sarah from Apex Dental Clinic. We noticed we missed your call — sorry for the inconvenience!\n\nAre you experiencing any dental pain, or would you like to schedule a routine cleaning/checkup? We have openings tomorrow — would morning or afternoon suit you best?`;

  } else {
    isBooked = false;
    stage = 'AWAITING_TIME';
    reply = `Got it, ${patientName}! We can definitely help you with ${currentService}. We have openings tomorrow morning (10:00 AM) and afternoon (2:00 PM, 4:00 PM). What time works best for you?`;
  }
}

// 4. Google Sheets & Session State Packaging
const triageStatus = isEmergency 
  ? 'HIGH PRIORITY / EMERGENCY (WHATSAPP RECOVERY)' 
  : (isBooked ? 'CONFIRMED BOOKING (WHATSAPP)' : 'INQUIRY / QUALIFYING');

const notes = isEmergency 
  ? `Sub-60s Auto-Recovery: Urgent dental emergency reported: "${messageText.slice(0, 100)}"` 
  : `WhatsApp Booking: Confirmed ${currentService} for ${currentTime || 'Tomorrow'}.`;

const safePhone = String(senderPhone).startsWith('+') ? `'${senderPhone}` : String(senderPhone);

const updatedSession = {
  patientName: patientName,
  senderPhone: senderPhone,
  service: currentService,
  preferredTime: currentTime,
  stage: stage,
  isBooked: isBooked,
  isEmergency: isEmergency,
  lastUpdated: new Date().toISOString()
};

return {
  json: {
    'TIMESTAMP': new Date().toLocaleString(),
    'PATIENT NAME': patientName,
    'PHONE NUMBER': safePhone,
    'SERVICE / REASON': currentService,
    'PREFERRED TIME': currentTime || 'Pending Confirmation',
    'TRIAGE STATUS': triageStatus,
    'NOTES': notes,
    'reply': reply,
    'isBooked': isBooked,
    'isEmergency': isEmergency,
    'updatedSession': updatedSession
  }
};

const item = $input.first().json;
return {
  json: {
    'TIMESTAMP': item['TIMESTAMP'],
    'PATIENT NAME': item['PATIENT NAME'],
    'PHONE NUMBER': item['PHONE NUMBER'],
    'SERVICE / REASON': item['SERVICE / REASON'],
    'PREFERRED TIME': item['PREFERRED TIME'],
    'TRIAGE STATUS': item['TRIAGE STATUS'],
    'NOTES': item['NOTES']
  }
};
